add_filter( 'language_attributes', function ( $out ) {
	if ( is_admin() ) { return $out; }
	if ( is_page( pbc_en_pages() ) || is_front_page() ) {
		return preg_replace( '/lang="[^"]*"/', 'lang="en-US"', $out );
	}
	return $out;
} );

